fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn hand(cx: i32, cy: i32, ang: i32, len: i32, rgb: i32) {
    let x: i32 = cx + sv(ang) * len / 127;
    let y: i32 = cy - sv(ang + 8) * len / 127;
    host::display::draw_line(cx, cy, x, y, rgb);
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let r: i32 = if w < h { w / 2 - 20 } else { h / 2 - 20 };
    host::display::clear(0x101018);
    let mut k: i32 = 0;
    while k < 12 {
        let a: i32 = k * 32 / 12;
        let tx: i32 = cx + sv(a) * r / 127;
        let ty: i32 = cy - sv(a + 8) * r / 127;
        host::display::fill_rect(tx - 2, ty - 2, 5, 5, 0x707070);
        k = k + 1;
    }
    let secs: i32 = t / 60 + 10 * 3600 + 8 * 60;
    let s: i32 = secs % 60;
    let m: i32 = (secs / 60) % 60;
    let hr: i32 = (secs / 3600) % 12;
    hand(cx, cy, hr * 32 / 12 + m * 32 / 720, r * 5 / 10, 0xffffff);
    hand(cx, cy, m * 32 / 60, r * 7 / 10, 0xc0c0c0);
    hand(cx, cy, s * 32 / 60, r * 9 / 10, 0xff5050);
    host::display::fill_rect(cx - 2, cy - 2, 5, 5, 0xffffff);
    host::display::present();
}
